#!/usr/bin/env python3
"""Patch: fix Shorts duration filter from 60s to 180s."""

import base64, os, subprocess

ROOT = os.path.expanduser("~/insight-dashboards")

API_B64 = (
    ""
)

files = {
    "dashboards/youtube/api.py": API_B64,
}

for rel_path, b64 in files.items():
    dest = os.path.join(ROOT, rel_path)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"  wrote {rel_path}")

# Commit and push
subprocess.run(["git", "-C", ROOT, "add", "-A"], check=True)
subprocess.run(
    ["git", "-C", ROOT, "commit", "-m", "fix: expand Shorts duration filter from 60s to 180s\n\nYouTube extended Shorts to 3 minutes; <= 60s was discarding most videos."],
    check=True,
)
subprocess.run(["git", "-C", ROOT, "push", "origin", "HEAD"], check=True)
print("Done — restart service and trigger refresh on NUC:")
print("  sudo systemctl restart insight-dashboards")
print("  curl -X POST http://localhost:8001/api/youtube/refresh")
print("  curl http://localhost:8001/api/youtube/videos | python3 -m json.tool")
